/*
 * Simple LED toggle on MCXC144 (Cortex‑M0+)
 *
 * - LED is connected to PTE24
 * - PTE24 is configured as a GPIO output
 * - The pin is toggled in an endless loop with a software delay
 *
 * Only MCUXpresso SDK driver headers and CMSIS are used.
 */

#include "fsl_clock.h"   /* Clock gating */
#include "fsl_port.h"    /* Pin muxing */
#include "fsl_gpio.h"    /* GPIO driver */
#include "core_cm0plus.h"/* CMSIS core (defines __NOP, etc.) */

/* ------------------------------------------------------------------------- */
/* Definitions                                                               */
/* ------------------------------------------------------------------------- */
#define LED_PORT        PORTE
#define LED_GPIO        GPIOE
#define LED_PIN         24U
#define LED_PIN_MASK    (1U << LED_PIN)

#define SOFTWARE_DELAY  500000U   /* Adjust for visible blink rate */

/* ------------------------------------------------------------------------- */
/* Simple busy‑wait delay                                                   */
/* ------------------------------------------------------------------------- */
static void delay(void)
{
    for (volatile uint32_t i = 0U; i < SOFTWARE_DELAY; ++i)
    {
        __NOP();                     /* Prevent optimizer from removing loop */
    }
}

/* ------------------------------------------------------------------------- */
/* Main entry                                                                */
/* ------------------------------------------------------------------------- */
int main(void)
{
    /* 1. Enable the clock for the PORT peripheral (GPIO registers are always
       clocked on this device, so no separate GPIO clock enable is required). */
    CLOCK_EnableClock(kCLOCK_PortE);

    /* 2. Configure PTE24 as GPIO */
    PORT_SetPinMux(LED_PORT, LED_PIN, kPORT_MuxAsGpio);

    /* 3. Initialize the pin as a digital output, initial level low */
    gpio_pin_config_t led_config = {
        kGPIO_DigitalOutput,
        0U
    };
    GPIO_PinInit(LED_GPIO, LED_PIN, &led_config);

    /* 4. Main loop – toggle the LED with a software delay */
    while (1)
    {
        GPIO_PortToggle(LED_GPIO, LED_PIN_MASK);  /* Toggle PTE24 */
        delay();                                   /* Simple busy‑wait */
    }
}

