/****************************************************************************************
 *  Bare‑metal demo for MCXC144 (Cortex‑M0+)
 *
 *  - PIT channel 0 generates an interrupt every 10 ms (bus clock = 48 MHz)
 *  - ISR samples pin PTC3 (digital input) and stores the value
 *  - ISR sets a flag to tell the main loop a new sample is ready
 *  - Main loop clears the flag, reads the sample and, if the pin is high,
 *    toggles LED on PTE24
 *
 *  Only MCUXpresso SDK driver headers are used (no board files, no raw device
 *  headers).
 ****************************************************************************************/

#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_pit.h"
#include "fsl_common.h"
#include "core_cm0plus.h"          /* CMSIS core header for __disable_irq etc. */

/* -------------------------------------------------------------------------- */
/*  Global data shared between ISR and main                                   */
/* -------------------------------------------------------------------------- */
static volatile bool     g_sampleReady = false;   /* flag set by ISR          */
static volatile uint8_t  g_lastSample  = 0;       /* last sampled pin state  */

/* -------------------------------------------------------------------------- */
/*  PIT interrupt handler                                                     */
/* -------------------------------------------------------------------------- */
void PIT_IRQHandler(void)
{
    /* Clear interrupt flag */
    PIT_ClearStatusFlags(PIT, kPIT_TimerFlag0);

    /* Read the input pin */
    g_lastSample = (uint8_t)GPIO_PinRead(GPIOC, 3U);

    /* Tell main loop that a new sample is available */
    g_sampleReady = true;
}

/* -------------------------------------------------------------------------- */
/*  Helper: toggle a GPIO output pin                                          */
/* -------------------------------------------------------------------------- */
static void ToggleLed(void)
{
    uint32_t cur = GPIO_PinRead(GPIOE, 24U);
    GPIO_PinWrite(GPIOE, 24U, (uint8_t)(!cur));
}

/* -------------------------------------------------------------------------- */
/*  Main entry point                                                          */
/* -------------------------------------------------------------------------- */
int main(void)
{
    /* ---------------------------------------------------------------------- */
    /*  1. Enable clock gates for PORTC, PORTE and PIT                        */
    /* ---------------------------------------------------------------------- */
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_PortE);
    CLOCK_EnableClock(kCLOCK_Pit);          /* PIT clock gate */

    /* ---------------------------------------------------------------------- */
    /*  2. Configure pins                                                     */
    /* ---------------------------------------------------------------------- */
    /* PTC3 as GPIO input */
    PORT_SetPinMux(PORTC, 3U, kPORT_MuxAsGpio);
    gpio_pin_config_t inPinCfg = {
        .pinDirection = kGPIO_DigitalInput,
        .outputLogic  = 0U
    };
    GPIO_PinInit(GPIOC, 3U, &inPinCfg);

    /* PTE24 as GPIO output (LED) */
    PORT_SetPinMux(PORTE, 24U, kPORT_MuxAsGpio);
    gpio_pin_config_t outPinCfg = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = 0U
    };
    GPIO_PinInit(GPIOE, 24U, &outPinCfg);

    /* ---------------------------------------------------------------------- */
    /*  3. Initialise PIT (channel 0, 10 ms period)                           */
    /* ---------------------------------------------------------------------- */
    pit_config_t pitCfg;
    PIT_GetDefaultConfig(&pitCfg);
    pitCfg.enableRunInDebug = false;               /* keep PIT stopped in debug */
    PIT_Init(PIT, &pitCfg);

    /* 48 MHz bus clock → 10 ms = 480 000 counts */
    PIT_SetTimerPeriod(PIT, kPIT_Ch0, 480000U);
    PIT_EnableInterrupts(PIT, kPIT_TimerFlag0);    /* enable interrupt source   */
    PIT_StartTimer(PIT, kPIT_Ch0);                /* start channel 0           */

    /* ---------------------------------------------------------------------- */
    /*  4. Enable PIT interrupt in the NVIC                                   */
    /* ---------------------------------------------------------------------- */
    EnableIRQ(PIT_IRQn);
    /* Ensure pending interrupt flag is cleared before entering the loop */
    __DSB();
    __ISB();

    /* ---------------------------------------------------------------------- */
    /*  5. Main processing loop                                                */
    /* ---------------------------------------------------------------------- */
    for (;;)
    {
        if (g_sampleReady)
        {
            /* Critical section: read & clear flag/sample atomically */
            __disable_irq();
            bool   ready = g_sampleReady;
            uint8_t sample = g_lastSample;
            g_sampleReady = false;
            __enable_irq();

            if (ready && (sample != 0U))
            {
                ToggleLed();
            }
        }
    }
}

