/*
 *  Simple bare‑metal example for the MCXC144 (Cortex‑M0+).
 *  Sends two bytes (0x9F, 0x00) over SPI0 and stores the two bytes
 *  received from the slave.
 *
 *  Pin assignment (see the MCXC144 datasheet for the ALT function numbers):
 *      PTC6  – SPI0_SCK   (ALT2)
 *      PTC7  – SPI0_MOSI  (ALT2)
 *      PTC4  – SPI0_MISO  (ALT2)
 *      PTC5  – GPIO output used as manual CS (active low)
 *
 *  The example uses only the MCUXpresso SDK driver headers:
 *      fsl_clock.h, fsl_port.h, fsl_gpio.h, fsl_spi.h
 *
 *  No board support files (board.h, pin_mux.h, …) are required.
 */

#include <stdint.h>
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_spi.h"

/* -------------------------------------------------------------------------- */
/*  Helper macros                                                             */
/* -------------------------------------------------------------------------- */
#define SPI_MASTER               SPI0
#define SPI_MASTER_CLK_SRC       kCLOCK_BusClk        /* Bus clock drives SPI0   */
#define SPI_MASTER_CLK_GATE      kCLOCK_Spi0          /* Clock gate for SPI0     */
#define PORTC_CLK_GATE           kCLOCK_PortC
#define GPIOC_CLK_GATE           kCLOCK_GpioC

/* Pin numbers on PORTC */
#define PIN_SCK      6U   /* PTC6 */
#define PIN_MOSI     7U   /* PTC7 */
#define PIN_MISO     4U   /* PTC4 */
#define PIN_CS       5U   /* PTC5 – manual CS */

/* -------------------------------------------------------------------------- */
/*  Global data                                                               */
/* -------------------------------------------------------------------------- */
static volatile uint8_t g_rxBuffer[2];   /* Received bytes from the slave */

/* -------------------------------------------------------------------------- */
/*  Function prototypes                                                       */
/* -------------------------------------------------------------------------- */
static void BOARD_InitPins(void);
static void BOARD_InitClocks(void);
static void BOARD_InitGPIO(void);
static void BOARD_InitSPI(void);

/* -------------------------------------------------------------------------- */
/*  Main                                                                      */
/* -------------------------------------------------------------------------- */
int main(void)
{
    /* 1. Enable required clocks and configure pins */
    BOARD_InitClocks();
    BOARD_InitPins();
    BOARD_InitGPIO();

    /* 2. Initialise SPI0 as master */
    BOARD_InitSPI();

    /* ---------------------------------------------------------------------- */
    /* 3. Transfer two bytes, using manual CS control                         */
    /* ---------------------------------------------------------------------- */
    const uint8_t txData[2] = { 0x9F, 0x00 };
    spi_transfer_t xfer = {
        .txData   = txData,
        .rxData   = (uint8_t *)g_rxBuffer,
        .dataSize = sizeof(txData),
        .flags    = kSPI_FrameAssert | kSPI_FrameDeassert,
    };

    /* Assert CS (active low) */
    GPIO_WritePinOutput(GPIOC, PIN_CS, 0U);

    /* Blocking transfer */
    (void)SPI_MasterTransferBlocking(SPI_MASTER, &xfer);

    /* De‑assert CS */
    GPIO_WritePinOutput(GPIOC, PIN_CS, 1U);

    /* The received bytes are now in g_rxBuffer[0] and g_rxBuffer[1] */
    while (1)
    {
        /* Application could use g_rxBuffer here … */
    }
}

/* -------------------------------------------------------------------------- */
/*  Clock initialisation – enable the peripherals we use                     */
/* -------------------------------------------------------------------------- */
static void BOARD_InitClocks(void)
{
    /* Enable the clocks for PORTC, GPIOC and SPI0 */
    CLOCK_EnableClock(PORTC_CLK_GATE);
    CLOCK_EnableClock(GPIOC_CLK_GATE);
    CLOCK_EnableClock(SPI_MASTER_CLK_GATE);
}

/* -------------------------------------------------------------------------- */
/*  Pin multiplexing – connect PORTC pins to the SPI0 signals               */
/* -------------------------------------------------------------------------- */
static void BOARD_InitPins(void)
{
    /* All pins are set to ALT2 for SPI0 on MCXC144 (see the device manual). */
    port_pin_config_t pinConfig = { kPORT_PullDisable, kPORT_FastSlewRate,
                                    kPORT_PassiveFilterDisable,
                                    kPORT_OpenDrainDisable,
                                    kPORT_LowDriveStrength,
                                    kPORT_MuxAlt2,
                                    kPORT_UnlockRegister };

    PORT_SetPinConfig(PORTC, PIN_SCK,  &pinConfig);
    PORT_SetPinConfig(PORTC, PIN_MOSI, &pinConfig);
    PORT_SetPinConfig(PORTC, PIN_MISO, &pinConfig);
}

/* -------------------------------------------------------------------------- */
/*  GPIO – configure PTC5 as a digital output (manual CS)                    */
/* -------------------------------------------------------------------------- */
static void BOARD_InitGPIO(void)
{
    gpio_pin_config_t csConfig = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = 1U,               /* De‑asserted (high) after reset */
    };

    GPIO_PinInit(GPIOC, PIN_CS, &csConfig);
}

/* -------------------------------------------------------------------------- */
/*  SPI0 – master mode, CPOL = 0, CPHA = 0, 1 MHz, 8‑bit frames            */
/* -------------------------------------------------------------------------- */
static void BOARD_InitSPI(void)
{
    spi_master_config_t spiConfig;

    SPI_MasterGetDefaultConfig(&spiConfig);

    spiConfig.baudRate_Bps = 1000000U;               /* 1 MHz */
    spiConfig.whichPcs      = kSPI_Pcs0;             /* not used – CS is manual */
    spiConfig.pcsActiveLow = kSPI_PcsActiveLow;     /* default */

    /* Initialise the peripheral */
    (void)SPI_MasterInit(SPI_MASTER, &spiConfig,
                         CLOCK_GetFreq(SPI_MASTER_CLK_SRC));
}

