/*
 *  Bare‑metal UART0 example for MCXC144 (Cortex‑M0+)
 *
 *  Sends "Hello\r\n" over UART0 at 115200 8N1 every second.
 *  Uses only MCUXpresso SDK driver headers – no board support files.
 */

#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_uart.h"

#include <stdint.h>
#include <stddef.h>

/*-----------------------------------------------------------*/
/*  UART configuration constants                              */
#define UART_INSTANCE          UART0
#define UART_CLK_SRC           kCLOCK_CoreSysClk   /* core/system clock */
#define UART_BAUD_RATE         115200U
#define UART_TX_PIN            2U   /* PTA2 */
#define UART_RX_PIN            1U   /* PTA1 */

/*-----------------------------------------------------------*/
/*  Simple software delay – approximate 1 second at 48 MHz    */
static void delay_1s(void)
{
    /* MCXC144 runs at 48 MHz after the default clock setup.
       Adjust the count if a different core clock is used. */
    for (volatile uint32_t i = 0U; i < 48000000U; ++i)
    {
        __NOP();
    }
}

/*-----------------------------------------------------------*/
int main(void)
{
    /*-------------------------------------------------------*/
    /* 1. Enable clocks for PORTA and UART0                    */
    CLOCK_EnableClock(kCLOCK_PortA);
    CLOCK_EnableClock(kCLOCK_Uart0);

    /*-------------------------------------------------------*/
    /* 2. Pin multiplexing                                    */
    /*    PTA1 → UART0_RX  (ALT2)                              */
    /*    PTA2 → UART0_TX  (ALT2)                              */
    PORT_SetPinMux(PORTA, UART_RX_PIN, kPORT_MuxAlt2);
    PORT_SetPinMux(PORTA, UART_TX_PIN, kPORT_MuxAlt2);

    /*-------------------------------------------------------*/
    /* 3. UART configuration                                   */
    uart_config_t uartConfig;
    UART_GetDefaultConfig(&uartConfig);

    uartConfig.baudRate_Bps   = UART_BAUD_RATE;
    uartConfig.parityMode     = kUART_ParityDisabled;
    uartConfig.stopBitCount   = kUART_OneStopBit;
    uartConfig.enableTx       = true;
    uartConfig.enableRx       = true;

    /* Initialise UART0 */
    UART_Init(UART_INSTANCE,
              &uartConfig,
              CLOCK_GetFreq(UART_CLK_SRC));

    /*-------------------------------------------------------*/
    /* 4. Main transmit loop                                   */
    const uint8_t msg[] = "Hello\r\n";
    const size_t  msgLen = sizeof(msg) - 1U;   /* exclude terminating NUL */

    for (;;)
    {
        UART_WriteBlocking(UART_INSTANCE, msg, (uint8_t)msgLen);
        delay_1s();
    }

    /* Unreachable, but required for ISO C */
    return 0;
}

