/****************************************************************************************
 *  Bare‑metal example for i.MX RT1170 (MIMXRT1176) – 512‑byte memory‑to‑memory copy
 *  using eDMA channel 0 (DMA0).  The source buffer is filled with the pattern
 *  (index & 0xFF) before the transfer.  After the DMA completes the destination
 *  buffer is compared with the source; a mismatch causes an infinite halt loop.
 *
 *  Only MCUXpresso SDK driver headers are used – no board support files.
 ****************************************************************************************/

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

