#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_edma.h"
#include "fsl_cache.h"

/*--------------------------------------------------------------
 *  Buffer definitions – aligned for DMA and placed in non‑cacheable
 *  memory region to avoid cache‑coherency problems on the Cortex‑M7.
 *-------------------------------------------------------------*/
#define BUFFER_SIZE 512U

/* Align to 32‑byte (cache line) boundary and place in a non‑cacheable section */
AT_NONCACHEABLE_SECTION_ALIGN(uint8_t srcBuffer[BUFFER_SIZE], 32);
AT_NONCACHEABLE_SECTION_ALIGN(uint8_t dstBuffer[BUFFER_SIZE], 32);

/*--------------------------------------------------------------
 *  Main program
 *-------------------------------------------------------------*/
int main(void)
{
    /*--------------------------------------------------------------------
     *  1. Enable clocks required for DMA0/eDMA.
     *--------------------------------------------------------------------*/
    CLOCK_EnableClock(kCLOCK_Dma0);          /* Clock gate for DMA0 (eDMA) */

    /*--------------------------------------------------------------------
