/*
 * Simple LED blink example for i.MX RT1170 (MIMXRT1176) using the MCUXpresso SDK.
 *
 * LED is connected to GPIO9 pin 3 (pad GPIO_AD_04).
 * The LED is turned off at startup and toggled every ~500 ms using a
 * software delay loop.
 *
 * Only SDK driver headers are used – no board support package files.
 */

#include <stdint.h>
#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_gpio.h"

/*-----------------------------------------------------------*/
/* Configuration */
#define LED_GPIO            GPIO9                /* GPIO instance */
#define LED_PIN             (3U)                 /* Pin number within the instance */
#define LED_PAD             IOMUXC_GPIO_AD_04_GPIO9_IO03 /* Pad‑to‑GPIO mux */

/* Approximate software delay for ~500 ms.
 * The loop count is calibrated for a typical 600 MHz core clock.
 * Adjust if the delay is far off on your board. */
#define DELAY_LOOP_COUNT    (600U * 1000U * 500U)   /* 600 MHz * 0.5 s */

/*-----------------------------------------------------------*/
static void BOARD_InitPins(void)
{
    /* Enable the IOMUXC clock (required for pin muxing). */
    CLOCK_EnableClock(kCLOCK_Iomuxc);

    /* Configure pad GPIO_AD_04 as GPIO9_IO03 (ALT5). */
    IOMUXC_SetPinMux(LED_PAD, 0U);
    /* Optional: set pad electrical characteristics (use default). */
    IOMUXC_SetPinConfig(LED_PAD, 0x10B0U);
}

/*-----------------------------------------------------------*/
static void BOARD_InitPeripherals(void)
{
    /* Enable the clock gate for GPIO9. */
    CLOCK_EnableClock(kCLOCK_Gpio9);

    /* Configure the LED pin as a digital output, initially low (LED off). */
    gpio_pin_config_t led_config = {
        kGPIO_DigitalOutput,   /* Pin direction */
        0U                     /* Initial output level: 0 = LED off */
    };
    GPIO_PinInit(LED_GPIO, LED_PIN, &led_config);
}

/*-----------------------------------------------------------*/
static void delay_approx_500ms(void)
{
    volatile uint32_t i;

    for (i = 0U; i < DELAY_LOOP_COUNT; ++i)
    {
        __NOP();   /* Prevent the loop from being optimised away */
    }
}

/*-----------------------------------------------------------*/
int main(void)
{
    /* System initialization (clock, etc.) */
    BOARD_InitPins();
    BOARD_InitPeripherals();

    while (1)
    {
        /* Toggle LED state. */
        GPIO_PortToggle(LED_GPIO, 1U << LED_PIN);

        /* Rough 500 ms delay. */
        delay_approx_500ms();
    }
}

