/****************************************************************************************
 *  Echo UART on i.MX RT1170 (MIMXRT1176) – Bare‑metal example
 *
 *  - UART   : LPUART1
 *  - Pins   : GPIO_AD_24 (LPUART1_TX)   -> IOMUXC_GPIO_AD_24_LPUART1_TX
 *             GPIO_AD_25 (LPUART1_RX)   -> IOMUXC_GPIO_AD_25_LPUART1_RX
 *  - Baud   : 115200, 8N1
 *
 *  This file is completely self‑contained and uses only the MCUXpresso SDK driver
 *  headers.  No board‑specific files (board.h, pin_mux.h, …) are required.
 ****************************************************************************************/
#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_lpuart.h"

/* -------------------------------------------------------------------------- */
/*  Helper: simple blocking read/write wrappers                               */
/* -------------------------------------------------------------------------- */
static void UART_SendByte(uint8_t c)
{
    /* LPUART_WriteBlocking will wait until the TX FIFO has space. */
    LPUART_WriteBlocking(LPUART1, &c, 1U);
}

static uint8_t UART_RecvByte(void)
{
    uint8_t c;
    /* Wait until a character is received. */
    LPUART_ReadBlocking(LPUART1, &c, 1U);
    return c;
}

/* -------------------------------------------------------------------------- */
/*  Main                                                                      */
/* -------------------------------------------------------------------------- */
int main(void)
{
    /* ---------------------------------------------------------------------- */
    /*  1. Enable the peripheral clock for LPUART1                              */
    /* ---------------------------------------------------------------------- */
    CLOCK_EnableClock(kCLOCK_Lpuart1);          /* Clock gate */

    /* Select the UART clock source (PLL3 80 MHz is the default for most SDKs) */
    /* The SDK provides a convenience function – use the default source.      */
    CLOCK_SetLpuartClock(1U);   /* 1 = PLL3 (80 MHz) – value taken from SDK examples */

    /* ---------------------------------------------------------------------- */
    /*  2. Pin multiplexing                                                    */
    /* ---------------------------------------------------------------------- */
    /* TX – GPIO_AD_24 -> LPUART1_TX */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_24_LPUART1_TX,   0U);
    /* RX – GPIO_AD_25 -> LPUART1_RX */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_25_LPUART1_RX,   0U);

    /* Optional: configure electrical properties (drive strength, pull‑up, …) */
    /* The value 0x10B0U is the same as used in the SDK pin‑mux examples.    */
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_24_LPUART1_TX,
                        IOMUXC_SW_PAD_CTL_PAD_SPEED(2U) |
                        IOMUXC_SW_PAD_CTL_PAD_DSE(6U)   |
                        IOMUXC_SW_PAD_CTL_PAD_PUE(1U)   |
                        IOMUXC_SW_PAD_CTL_PAD_PKE(1U)   |
                        IOMUXC_SW_PAD_CTL_PAD_ODE(0U)   |
                        IOMUXC_SW_PAD_CTL_PAD_HYS(0U));

    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_25_LPUART1_RX,
                        IOMUXC_SW_PAD_CTL_PAD_SPEED(2U) |
                        IOMUXC_SW_PAD_CTL_PAD_DSE(6U)   |
                        IOMUXC_SW_PAD_CTL_PAD_PUE(1U)   |
                        IOMUXC_SW_PAD_CTL_PAD_PKE(1U)   |
                        IOMUXC_SW_PAD_CTL_PAD_ODE(0U)   |
                        IOMUXC_SW_PAD_CTL_PAD_HYS(0U));

    /* ---------------------------------------------------------------------- */
    /*  3. LPUART configuration                                                */
    /* ---------------------------------------------------------------------- */
    lpuart_config_t uartConfig;
    LPUART_GetDefaultConfig(&uartConfig);

    uartConfig.baudRate_Bps = 115200U;
    uartConfig.parityMode   = kLPUART_ParityDisabled;
    uartConfig.stopBitCount = kLPUART_OneStopBit;
    uartConfig.enableTx     = true;
    uartConfig.enableRx     = true;

    /* Get the UART clock frequency (after the clock source selection above). */
    uint32_t uartClockFreq = CLOCK_GetFreq(kCLOCK_UartClk);

    /* Initialize LPUART1 */
    LPUART_Init(LPUART1, &uartConfig, uartClockFreq);

    /* ---------------------------------------------------------------------- */
    /*  4. Echo loop – read a byte and write it back immediately                */
    /* ---------------------------------------------------------------------- */
    for (;;)
    {
        uint8_t ch = UART_RecvByte();   /* Blocking receive */
        UART_SendByte(ch);              /* Immediate echo   */
    }
}

